'use strict';
const $=(s,c=document)=>c.querySelector(s);
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',pitch:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M12 4v16M2 9h4v6H2m20-6h-4v6h4"/><circle cx="12" cy="12" r="3"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 3a6 6 0 0 1 3 5v2"/>',compare:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',chart:'<path d="M3 3v18h18M7 15l5-5 4 3 5-7"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 15v6h16v-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',star:'<path d="m12 2 3 7 7 .7-5.3 4.8 1.7 7-6.4-3.8L5.6 22l1.7-7L2 9.7 7 9Z"/>',cup:'<path d="M7 3h10v6a5 5 0 0 1-10 0ZM7 5H3v3a4 4 0 0 0 5 4m9-7h4v3a4 4 0 0 1-5 4m-4 2v7m-5 0h10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 3"/>'};
const icon=(name)=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.grid}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
const fmt=n=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(n);
const teams=[['Nam Định','NĐ','#b69c45'],['Công an Hà Nội','CA','#ba4048'],['Hà Nội','HN','#735ab0'],['Thể Công Viettel','VT','#b8474c'],['Thanh Hóa','TH','#c29a23'],['Hải Phòng','HP','#b34743'],['Hồng Lĩnh Hà Tĩnh','HT','#a04350'],['Sông Lam Nghệ An','NA','#cfb32a'],['Hoàng Anh Gia Lai','GL','#547ca4'],['Ninh Bình','NB','#6461a3'],['Becamex TP.HCM','BC','#4571a3'],['Công an TP.HCM','HC','#bc424b'],['PVF CAND','PV','#a75039'],['SHB Đà Nẵng','ĐN','#d37c39'],['Đồng Tháp','ĐT','#c3a339'],['Long An','LA','#9d4949']];
// All player statistics and club associations below are synthetic demonstration records.
const raw=[['Nguyễn Hoàng Đức',9,'CM',28,1480,6,7,88,35,29,6.3,4.8],['Nguyễn Quang Hải',1,'AM',29,1395,7,6,86,42,17,5.1,5.8],['Nguyễn Tiến Linh',10,'ST',29,1452,12,3,78,20,9,10.6,2.1],['Phạm Tuấn Hải',2,'LW',28,1370,9,4,82,25,18,8.2,3.4],['Nguyễn Văn Toàn',0,'RW',30,1240,5,7,81,29,13,4.7,4.3],['Nguyễn Văn Quyết',2,'AM',35,1220,6,5,87,31,12,5.4,4.1],['Nguyễn Văn Vĩ',0,'LB',28,1480,3,5,84,21,41,2.1,3.6],['Nguyễn Hai Long',2,'CM',26,1210,4,4,86,25,27,3.2,3.1],['Bùi Hoàng Việt Anh',1,'CB',27,1530,2,1,91,8,49,1.5,.8],['Nguyễn Thành Chung',2,'CB',29,1450,1,2,90,10,45,.9,1.1],['Đỗ Hùng Dũng',2,'CM',33,1185,2,4,90,22,32,1.7,3.2],['Vũ Văn Thanh',1,'RB',30,1335,3,4,83,24,37,2.7,3.4],['Châu Ngọc Quang',8,'CM',30,1440,5,3,84,21,30,4.1,2.7],['Quế Ngọc Hải',10,'CB',33,1350,1,1,89,9,41,.8,.9],['Nguyễn Đình Triệu',5,'GK',35,1530,0,0,76,1,3,0,0],['Đặng Văn Lâm',9,'GK',33,1530,0,0,79,0,2,0,0],['Đinh Thanh Bình',14,'ST',28,1350,9,3,77,15,11,7.8,2.2],['Lê Minh Bình',15,'ST',27,1290,8,4,79,21,14,7.1,3.2]];
const players=raw.map((r,i)=>({id:i,name:r[0],team:r[1],pos:r[2],age:r[3],minutes:r[4],goals:r[5],assists:r[6],pass:r[7],key:r[8],tackles:r[9],xg:r[10],xa:r[11],matches:17,league:i<16?'V.League 1':'V.League 2',saves:r[2]==='GK'?54+i:0,conceded:r[2]==='GK'?18:0}));
const p90=(p,key)=>p[key]*90/p.minutes;
function rate(p){const attack=['ST','LW','RW'].includes(p.pos);const defense=['CB','LB','RB'].includes(p.pos);let n=6+(p.pass-75)*.02;if(p.pos==='GK')n+=p90(p,'saves')*.32-p90(p,'conceded')*.35;else n+=p90(p,'goals')*(attack?1.8:2.1)+p90(p,'assists')*1.6+p90(p,'key')*.25+p90(p,'tackles')*(defense?.4:.12);return Math.max(1,Math.min(10,n));}
function value(p,age=p.age,minutes=p.minutes,score=rate(p)){const ageFactor=age<=24?1.2:age<=28?1:Math.max(.4,1-(age-28)*.07);return Math.round(200000*Math.pow(score/7,2.3)*ageFactor*Math.min(1.2,minutes/1500)/10000)*10000;}
const euro=n=>fmt(n/1000)+' nghìn €';
const badge=p=>`<span class="rating ${rate(p)>=7.5?'top':rate(p)<7?'mid':''}">${rate(p).toFixed(2)}</span>`;
const avatar=p=>`<span class="player-avatar" style="--avatar-color:${['#e2eada','#e5e6dc','#e0e9eb','#eee5d9'][p.id%4]}">${p.name.split(' ').slice(-2).map(w=>w[0]).join('')}</span>`;
const crest=t=>`<span class="crest" style="--club-color:${teams[t][2]}">${teams[t][1]}</span>`;
const history=p=>Array.from({length:6},(_,i)=>({round:12+i,opponent:teams[(p.team+i+2)%14][0],minutes:i%3===0?75:90,rating:Math.max(5,Math.min(9.9,rate(p)+Math.sin((i+1)*(p.id+1))*.8)),goals:p.goals>0&&i%3===p.id%3?1:0}));
const nav=[['overview','Tổng quan','grid'],['matches','Trận đấu','pitch'],['players','Cầu thủ','people'],['compare','So sánh cầu thủ','compare'],['valuation','Định giá','chart'],['sources','Nguồn dữ liệu','database']];
const state={page:'overview',league:'V.League 1',position:'all',sort:'rating',search:'',matchFilter:'all',compare:[0,1],detailTab:'overview',selected:0,heatPlayer:0};
const matches=[{id:0,home:2,away:1,a:2,b:1,time:"67′",status:'live',ground:'Hàng Đẫy',xg:[1.68,.94]},{id:1,home:0,away:3,a:3,b:2,time:'KT',status:'finished',ground:'Thiên Trường',xg:[2.31,1.56]},{id:2,home:4,away:5,a:0,b:0,time:'19:15',status:'upcoming',ground:'Thanh Hóa',xg:[0,0]},{id:3,home:8,away:6,a:1,b:1,time:'KT',status:'finished',ground:'Pleiku',xg:[1.1,1.3]},{id:4,home:7,away:13,a:2,b:0,time:'KT',status:'finished',ground:'Vinh',xg:[1.8,.6]},{id:5,home:9,away:10,a:1,b:0,time:'HT',status:'live',ground:'Ninh Bình',xg:[.8,.4]}];
const officialURL='https://vpf.vn/tin-tuc/tin-vleague/so-lieu-chuyen-mon-sau-vong-18-vdqg-lpbank-2025-26/';
const official=[['Thể Công Viettel','Thanh Hóa','1–0','Hàng Đẫy',7600,11,1],['Sông Lam Nghệ An','SHB Đà Nẵng','1–0','Vinh',4000,4,0],['Nam Định','Hoàng Anh Gia Lai','1–2','Thiên Trường',8000,1,0],['Becamex TP.HCM','Ninh Bình','1–2','Bình Dương',3500,6,0],['Hải Phòng','Công an TP.HCM','3–0','Lạch Tray',6000,6,0],['PVF CAND','Công an Hà Nội','1–1','PVF',5000,9,0],['Hà Nội','Hồng Lĩnh Hà Tĩnh','3–0','Hàng Đẫy',8000,5,0]];
const sampleNote=()=>`<p class="data-note">${icon('info')} Phân tích thử nghiệm: chỉ số, đội hình, định giá và hồ sơ cầu thủ là dữ liệu minh họa, không phải dữ liệu Opta. <a class="text-link" href="#sources">Xem nguồn ↗</a></p>`;
function heading(title,sub,controls=''){return `<div class="page-heading"><div><div class="eyebrow">BÓNG ĐÁ VIỆT NAM, QUA TỪNG CON SỐ</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-controls">${controls||'<span class="select">Mùa mẫu 2025/26</span><span class="sample-tag">Dữ liệu minh họa</span>'}</div></div>`;}
function metric(title,n,bottom,ic='chart'){return `<div class="metric"><div class="metric-top">${title}${icon(ic)}</div><div class="metric-value">${n}</div><div class="metric-bottom">${bottom}</div></div>`;}
function getPlayers(){return players.filter(p=>p.league===state.league).filter(p=>state.position==='all'||(state.position==='FW'?['ST','LW','RW']:state.position==='MF'?['CM','AM']:state.position==='DF'?['CB','LB','RB']:['GK']).includes(p.pos)).filter(p=>norm(p.name+' '+teams[p.team][0]).includes(norm(state.search))).sort((a,b)=>state.sort==='value'?value(b)-value(a):state.sort==='goals'?b.goals-a.goals:state.sort==='xg'?b.xg-a.xg:rate(b)-rate(a));}
function playerRows(list,full=false){return list.map((p,i)=>`<tr><td><span class="rank">${i+1}</span></td><td><button class="row-player" data-player="${p.id}">${avatar(p)}<span><span class="player-name">${p.name}</span><span class="player-club" style="display:block">${teams[p.team][0]}</span></span></button></td><td><span class="position">${p.pos}</span></td>${full?`<td>${p.age}</td><td>${fmt(p.minutes)}</td>`:''}<td>${p.goals}</td><td>${p.assists}</td><td>${p.xg.toFixed(1)}</td><td>${badge(p)}</td>${full?`<td>${euro(value(p))}</td>`:''}</tr>`).join('');}
function playerTable(list,full=false){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Cầu thủ</th><th>Vị trí</th>${full?'<th>Tuổi</th><th>Phút</th>':''}<th title="Bàn thắng">Bàn</th><th title="Kiến tạo">KT</th><th title="Bàn thắng kỳ vọng — minh họa">xG</th><th>Điểm LD</th>${full?'<th>Định giá mẫu</th>':''}</tr></thead><tbody>${playerRows(list,full)}</tbody></table>${!list.length?'<div class="empty">Không tìm thấy cầu thủ phù hợp. Hãy thử tên hoặc vị trí khác.</div>':''}</div>`;}
function pills(){return `<div class="filter-pills">${[['all','Tất cả'],['FW','Tiền đạo'],['MF','Tiền vệ'],['DF','Hậu vệ'],['GK','Thủ môn']].map(([id,n])=>`<button class="pill ${state.position===id?'active':''}" data-position="${id}" aria-pressed="${state.position===id}">${n}</button>`).join('')}</div>`;}
function matchCard(m){return `<button class="match-card" data-match="${m.id}" aria-label="Xem trận mẫu ${teams[m.home][0]} gặp ${teams[m.away][0]}"><div class="match-meta"><span>V.LEAGUE 1 · VÒNG MẪU 18</span><span class="status ${m.status==='live'?'live':''}">${m.status==='live'?'Mô phỏng · ':''}${m.time}</span></div><div class="match-teams"><div class="match-team">${crest(m.home)}${teams[m.home][0]}</div><div class="score">${m.status==='upcoming'?'–':m.a}<span>:</span>${m.status==='upcoming'?'–':m.b}</div><div class="match-team away">${crest(m.away)}${teams[m.away][0]}</div></div><div class="match-bottom"><span>${m.ground}</span><b>${m.status==='upcoming'?'Xem trước trận →':`xG ${m.xg[0].toFixed(2)} – ${m.xg[1].toFixed(2)} →`}</b></div></button>`;}
let heatId=0;
function heatmap(p){const id='heat'+heatId++;const y=p.pos==='LW'?42:p.pos==='RW'?167:108;const x=['CB','GK'].includes(p.pos)?90:p.pos==='ST'?280:205;return `<div class="heatmap"><svg viewBox="0 0 360 210" role="img" aria-label="Bản đồ nhiệt minh họa của ${p.name}, vùng hoạt động tập trung ở ${p.pos}"><defs><radialGradient id="${id}"><stop offset="0" stop-color="#f54d37" stop-opacity=".94"/><stop offset=".27" stop-color="#ffc841" stop-opacity=".87"/><stop offset=".6" stop-color="#b4d54b" stop-opacity=".62"/><stop offset="1" stop-color="#41b96c" stop-opacity="0"/></radialGradient></defs><rect width="360" height="210" fill="#193e2c"/>${[0,2,4,6].map(i=>`<rect x="${i*45}" width="45" height="210" fill="#234b34" opacity=".55"/>`).join('')}<ellipse cx="${x}" cy="${y}" rx="94" ry="74" fill="url(#${id})"/><ellipse cx="${x+39}" cy="${y-15}" rx="64" ry="49" fill="url(#${id})"/><ellipse cx="${x-67}" cy="${y+15}" rx="66" ry="42" fill="url(#${id})"/><g stroke="#bad7a7" stroke-width="1" opacity=".65" fill="none"><rect x="12" y="12" width="336" height="186"/><path d="M180 12v186M12 60h53v90H12m336-90h-53v90h53M12 82h20v46H12m336-46h-20v46h20"/><circle cx="180" cy="105" r="29"/><circle cx="180" cy="105" r="2" fill="#bad7a7"/></g></svg></div><div class="heatmap-legend"><span>Hướng tấn công →</span><span>Ít <i class="legend-gradient"></i> Nhiều</span></div>`;}
function radar(p){const values=[Math.min(95,30+p90(p,'goals')*85),Math.min(95,35+p90(p,'key')*22),p.pass,Math.min(95,30+p90(p,'tackles')*21),60+(p.id%4)*7];const points=(factor)=>values.map((v,i)=>{let a=(i*72-90)*Math.PI/180;return `${150+Math.cos(a)*v*factor},${123+Math.sin(a)*v*factor}`}).join(' ');const outer=(r)=>Array.from({length:5},(_,i)=>{let a=(i*72-90)*Math.PI/180;return `${150+Math.cos(a)*r},${123+Math.sin(a)*r}`}).join(' ');return `<svg class="radar" viewBox="0 0 300 250" role="img" aria-label="Chỉ số kỹ chiến thuật minh họa: tấn công, sáng tạo, chuyền bóng, phòng ngự, tranh chấp"><g fill="none" stroke="#e0e8da">${[20,40,60,80,100].map(r=>`<polygon points="${outer(r)}"/>`).join('')}</g><polygon points="${points(.94)}" fill="#449d6340" stroke="#3a8a55" stroke-width="2"/><g fill="#7f9076" font-size="11" text-anchor="middle" font-family="Arial"><text x="150" y="14">Tấn công</text><text x="261" y="95">Sáng tạo</text><text x="226" y="222">Chuyền bóng</text><text x="75" y="222">Phòng ngự</text><text x="41" y="95">Tranh chấp</text></g></svg>`;}
function spotlight(p){return `<div class="panel spotlight"><div class="spotlight-top"><h2>Tâm điểm cầu thủ</h2>${icon('star')}</div><div class="spotlight-eyebrow">NỔI BẬT TRONG BỘ MẪU</div><div class="spotlight-profile">${avatar(p)}<div><h3>${p.name}</h3><p>${teams[p.team][0]} <span>·</span> ${p.pos}</p></div></div><div class="spotlight-rating"><div><strong>${rate(p).toFixed(2)}</strong><p>Điểm LockerData / 10</p></div><div class="mini-bars">${history(p).map(x=>`<i style="height:${(x.rating-5)*12}px" title="Vòng mẫu ${x.round}: ${x.rating.toFixed(2)}"></i>`).join('')}</div></div><div class="spotlight-stats"><div><b>${p.goals}</b><span>Bàn thắng</span></div><div><b>${p.assists}</b><span>Kiến tạo</span></div><div><b>${p.matches}</b><span>Trận mẫu</span></div></div><button class="button" data-player="${p.id}">Khám phá hồ sơ ${icon('arrow')}</button></div>`;}
const standings=[[0,17,11,3,3,16],[1,17,10,4,3,14],[2,17,9,5,3,12],[3,17,9,4,4,9],[4,17,8,4,5,7],[9,17,7,6,4,6],[5,17,7,4,6,3],[6,17,6,5,6,1],[8,17,5,6,6,-2],[10,17,5,4,8,-5],[7,17,4,6,7,-6],[11,17,4,4,9,-9],[12,17,3,5,9,-12],[13,17,3,3,11,-16]];
function ranking(full=false){return `<div class="table-wrap"><table class="mini-ranking"><thead><tr><th>#</th><th>Câu lạc bộ</th><th>Tr</th>${full?'<th>T</th><th>H</th><th>B</th><th>HS</th>':'<th>Phong độ</th>'}<th>Đ</th></tr></thead><tbody>${standings.slice(0,full?14:5).map((s,i)=>`<tr><td>${i+1}</td><td><div style="display:flex;gap:9px;align-items:center">${crest(s[0])}<span>${teams[s[0]][0]}</span></div></td><td>${s[1]}</td>${full?`<td>${s[2]}</td><td>${s[3]}</td><td>${s[4]}</td><td>${s[5]>0?'+':''}${s[5]}</td>`:`<td><div class="form"><span>T</span><span class="d">H</span><span>T</span></div></td>`}<td><b>${s[2]*3+s[3]}</b></td></tr>`).join('')}</tbody></table></div>`;}
function overview(){const list=getPlayers(),p=players[state.league==='V.League 1'?0:16];const all=players.filter(p=>p.league===state.league);return heading(`Khám phá ${state.league}`,'Hiểu trận đấu. Đọc vị phong độ. Nhìn ra tiềm năng.')+`<div class="top-tabs"><button class="top-tab active">Tổng quan</button><a class="top-tab" href="#matches">Trận đấu</a><button class="top-tab" data-action="standings">Bảng xếp hạng</button><a class="top-tab" href="#players">Thống kê cầu thủ</a></div><div class="metrics">${metric('Cầu thủ trong bộ mẫu',all.length,'Hồ sơ có thể khám phá','people')}${metric('Câu lạc bộ',new Set(all.map(p=>p.team)).size,'Trong bộ dữ liệu minh họa','cup')}${metric('Bàn thắng mẫu',all.reduce((n,p)=>n+p.goals,0),'Tổng của các hồ sơ cầu thủ','pitch')}${metric('Điểm trung bình',(all.reduce((n,p)=>n+rate(p),0)/all.length).toFixed(2),'Thuật toán LockerData · thử nghiệm','chart')}</div><div class="section-heading"><h2>Nhịp đập trận đấu <span class="subtitle">Vòng mẫu 18</span></h2><a class="text-link" href="#matches">Tất cả trận đấu →</a></div>${state.league==='V.League 1'?`<div class="matches">${matches.slice(0,3).map(matchCard).join('')}</div>`:'<div class="panel empty" style="margin-bottom:24px">Chưa có trận đấu trong bộ mẫu V.League 2. <a class="external" href="https://vpf.vn/mobile/#m-hang-nhat" target="_blank" rel="noopener">Xem Hạng Nhất trên VPF ↗</a></div>'}<div class="main-grid"><section class="panel"><div class="panel-header"><div><h2>Cầu thủ nổi bật</h2><p>Hiệu suất mùa giải · Bộ dữ liệu mẫu</p></div><a class="text-link" href="#players">Xem tất cả ↗</a></div>${pills()}${playerTable(list.slice(0,6))}<div class="table-footer"><span>Điểm LD: thang 1–10</span><a href="#sources">Cách tính điểm ↗</a></div></section><div class="right-column">${spotlight(p)}<div class="panel value-card"><div class="value-label">ĐỊNH GIÁ THỬ NGHIỆM · ${p.name.split(' ').slice(-2).join(' ').toUpperCase()}</div><strong>${euro(value(p))}</strong><div class="value-sub">Mô hình hiệu suất × độ tuổi × thời lượng</div><svg viewBox="0 0 260 55" role="img" aria-label="Đồ thị minh họa xu hướng giá trị"><path d="M0 48L26 45 53 47 80 33 107 35 133 25 160 27 186 16 214 19 240 6 260 8V55H0Z" fill="#eef4e8"/><path d="M0 48L26 45 53 47 80 33 107 35 133 25 160 27 186 16 214 19 240 6 260 8" stroke="#5d935e" fill="none" stroke-width="2"/></svg><a href="#valuation" class="text-link">Khám phá mô hình →</a></div></div></div><div class="bottom-grid"><section class="panel"><div class="panel-header"><div><h2>Không gian hoạt động</h2><p>Bản đồ nhiệt · Minh họa vị trí chạm bóng</p></div><select id="heat-player" class="small-select" aria-label="Cầu thủ trên bản đồ nhiệt">${all.map(p=>`<option value="${p.id}" ${p.id===state.heatPlayer?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="chart-inner" id="overview-heat">${heatmap(all.find(p=>p.id===state.heatPlayer)||p)}</div></section><section class="panel"><div class="panel-header"><div><h2>Cuộc đua ${state.league}</h2><p>Xếp hạng minh họa, không phải BXH chính thức</p></div><button class="text-link" data-action="standings">Chi tiết ↗</button></div>${state.league==='V.League 1'?ranking():`<div class="empty">Chưa có bảng xếp hạng mẫu V.League 2.</div>`}</section></div>${sampleNote()}`;}
function playersPage(){const list=getPlayers();return heading('Kho hồ sơ cầu thủ',`Khám phá, sàng lọc và đánh giá cầu thủ ${state.league}.`)+`<section class="panel"><div class="panel-header"><div><h2>Cơ sở dữ liệu cầu thủ <span class="tab-count">${list.length}</span></h2><p>Thống kê mùa mẫu 2025/26 · Tên thật, số liệu minh họa</p></div><button class="button" data-action="export">${icon('download')}Xuất CSV</button></div><div class="toolbar"><div class="toolbar-left"><input class="search-field" id="player-search" aria-label="Lọc cầu thủ" placeholder="Tên cầu thủ hoặc câu lạc bộ…" value="${esc(state.search)}"><select class="select" id="player-sort" aria-label="Sắp xếp cầu thủ">${[['rating','Điểm cao nhất'],['goals','Nhiều bàn thắng'],['xg','xG cao nhất'],['value','Định giá cao nhất']].map(([id,label])=>`<option value="${id}" ${state.sort===id?'selected':''}>${label}</option>`).join('')}</select></div></div>${pills()}<div id="player-results">${playerTable(list,true)}</div><div class="table-footer"><span>Chọn cầu thủ để xem hồ sơ và lịch sử trận đấu</span><span>${state.league}</span></div></section>${sampleNote()}`;}
function matchesPage(){return heading('Trung tâm trận đấu','Từ diễn biến trên sân đến những con số phía sau.')+`<div class="top-tabs">${[['all','Tất cả trận mẫu'],['live','Đang diễn ra · mô phỏng'],['finished','Đã kết thúc'],['official','Kết quả thực tế VPF']].map(([id,label])=>`<button class="top-tab ${state.matchFilter===id?'active':''}" data-match-filter="${id}">${label}</button>`).join('')}</div>${state.matchFilter==='official'?officialView():state.league==='V.League 2'?'<div class="panel empty">Chưa có dữ liệu trận đấu V.League 2. Xem nguồn chính thức trong mục Nguồn dữ liệu.</div>':`<div class="section-heading"><h2>V.League 1 <span class="subtitle">Vòng mẫu 18</span></h2><span class="sample-tag">Không phải tỉ số trực tiếp</span></div><div class="matches all-matches">${matches.filter(m=>state.matchFilter==='all'||m.status===state.matchFilter).map(matchCard).join('')}</div><p class="detail-note">Các trận mô phỏng được giữ cố định để trải nghiệm phân tích. Chưa có nguồn tỉ số trực tiếp được kết nối.</p>${sampleNote()}`}`;}
function officialView(){return `<div class="source-banner">Dữ liệu thực tế từ <a href="${officialURL}" target="_blank" rel="noopener">báo cáo VPF ngày 13/04/2026 ↗</a>. Bản trích dẫn tĩnh vòng 18 mùa 2025/26, kiểm tra ngày 23/09/2026; không cập nhật trực tiếp.</div><div class="metrics">${metric('Bàn thắng vòng 18','16','Nguồn: VPF','pitch')}${metric('Khán giả','42.100','Tổng 7 trận','people')}${metric('Thẻ vàng','42','Nguồn: VPF','info')}${metric('Thẻ đỏ','1','Nguồn: VPF','info')}</div><section class="panel"><div class="panel-header"><h2>Kết quả thực tế · Vòng 18</h2><span class="source-status">Nguồn VPF</span></div><div class="table-wrap"><table><thead><tr><th>Chủ nhà</th><th>Tỉ số</th><th>Khách</th><th>Sân</th><th>Khán giả</th></tr></thead><tbody>${official.map(r=>`<tr><td>${r[0]}</td><td><strong>${r[2]}</strong></td><td>${r[1]}</td><td>${r[3]}</td><td>${fmt(r[4])}</td></tr>`).join('')}</tbody></table></div><p class="form-note">Nguồn này không cung cấp xG, điểm cầu thủ hay tọa độ sự kiện cho các trận trên. Các chỉ số thiếu được để trống.</p></section>`;}
function comparePage(){const list=players.filter(p=>p.league===state.league);if(!list.some(p=>p.id===state.compare[0]))state.compare=[list[0].id,list[1].id];const a=players[state.compare[0]],b=players[state.compare[1]];const cards=[a,b].map((p,i)=>`<section class="panel compare-card ${i?'second':''}"><div class="profile-header">${avatar(p)}<div><h2>${p.name}</h2><p>${teams[p.team][0]} · ${p.pos}</p></div></div>${radar(p)}${[['Điểm LockerData',rate(p),10],['Bàn thắng / 90 phút',p90(p,'goals'),1.5],['Kiến tạo / 90 phút',p90(p,'assists'),1],['xG / 90 phút',p90(p,'xg'),1],['Đường chuyền tạo cơ hội / 90',p90(p,'key'),4],['Tắc bóng / 90 phút',p90(p,'tackles'),5],['Chuyền chính xác (%)',p.pass,100]].map(([n,v,max])=>`<div class="compare-row"><div class="labels"><span>${n}</span><b>${v.toFixed(2)}</b></div><div class="bar-track"><i style="width:${Math.min(100,v/max*100)}%"></i></div></div>`).join('')}<div class="detail-note">${fmt(p.minutes)} phút thi đấu mẫu · Định giá ${euro(value(p))}</div></section>`).join('');return heading('Hai cầu thủ. Một góc nhìn.','Đặt hiệu suất cạnh nhau với các chỉ số chuẩn hóa trên 90 phút.')+`<div class="compare-selects">${[0,1].map((n)=>`${n?'<div class="versus">VS</div>':''}<select class="select" id="compare-${n}" aria-label="Cầu thủ ${n+1}">${list.map(p=>`<option value="${p.id}" ${p.id===state.compare[n]?'selected':''}>${p.name} · ${p.pos}</option>`).join('')}</select>`).join('')}</div>${a.id===b.id?'<div class="source-banner">Bạn đang xem cùng một cầu thủ ở cả hai cột. Chọn một cầu thủ khác để so sánh.</div>':''}<div class="compare-grid">${cards}</div>${sampleNote()}`;}
function valuationPage(){const all=players.filter(p=>p.league===state.league);const p=all.find(p=>p.id===state.selected)||all[0];state.selected=p.id;return heading('Định giá từ hiệu suất','Thử các giả định và xem tác động lên mô hình giá trị cầu thủ.')+`<div class="panel method"><div class="value-model"><div><h2>Mô phỏng giá trị cầu thủ</h2><select class="select" style="width:100%" id="value-player" aria-label="Chọn cầu thủ định giá">${all.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.name}</option>`).join('')}</select><div class="value-slider"><label for="age-range">Độ tuổi <b id="age-val">${p.age}</b></label><input id="age-range" type="range" min="18" max="40" value="${p.age}"><label for="minute-range">Phút thi đấu trong mùa <b id="minute-val">${p.minutes}</b></label><input id="minute-range" type="range" min="90" max="2700" step="15" value="${p.minutes}"><label for="score-range">Điểm hiệu suất <b id="score-val">${rate(p).toFixed(2)}</b></label><input id="score-range" type="range" min="5" max="10" step=".01" value="${rate(p).toFixed(2)}"></div></div><div><div class="valuation-output"><span>GIÁ TRỊ MÔ HÌNH THỬ NGHIỆM</span><strong id="value-output">${euro(value(p))}</strong><p id="value-range">Dải kịch bản ±25%: ${euro(value(p)*.75)} – ${euro(value(p)*1.25)}</p></div><p>Đây là mô hình minh họa, chưa được hiệu chỉnh bằng dữ liệu chuyển nhượng. Không phải giá thị trường, báo giá giao dịch hay định giá của Transfermarkt.</p><p>Dải ±25% là mức thay đổi giả định, không phải khoảng tin cậy thống kê. Hợp đồng, chấn thương, điều khoản chuyển nhượng và sức mua chưa được đưa vào mô hình.</p><a href="#sources" class="text-link">Xem công thức và giới hạn →</a></div></div></div><section class="panel section-gap"><div class="panel-header"><h2>Xếp hạng giá trị trong bộ mẫu</h2><span class="sample-tag">Ước tính thử nghiệm</span></div>${playerTable([...all].sort((a,b)=>value(b)-value(a)).slice(0,8),true)}</section>${sampleNote()}`;}
function sourcesPage(){return heading('Dữ liệu có xuất xứ. Phân tích có cơ sở.','Nguồn đã tìm thấy và trạng thái kết nối của LockerData.VN.','<span class="select">Kiểm tra: 23/09/2026</span>')+`<div class="source-banner">Đã có bản trích dẫn kết quả thực tế VPF. Tỉ số trực tiếp, hồ sơ chi tiết và dữ liệu sự kiện chưa kết nối. <a href="#matches" data-official="true">Xem dữ liệu thực tế →</a></div><div class="sources-grid"><section class="panel source-card"><span class="source-status">Có trích dẫn thực tế</span><h2>VPF</h2><p>Nguồn chính thức bóng đá chuyên nghiệp Việt Nam.</p><ul class="source-list"><li>Báo cáo chuyên môn theo vòng</li><li>Kết quả, thẻ phạt, khán giả</li><li>Đã trích 7 trận vòng 18 · 2025/26</li></ul><p>Dữ liệu tĩnh có dẫn nguồn. Chưa xác minh được API công khai dành cho tự động đồng bộ.</p><a class="button" href="${officialURL}" target="_blank" rel="noopener">Mở báo cáo gốc ↗</a></section><section class="panel source-card"><span class="source-status pending">Chưa kết nối · Cần API key</span><h2>API-Football</h2><p>Danh sách bao phủ có V.League 1 và V.League 2.</p><ul class="source-list"><li>Free: 100 yêu cầu/ngày</li><li>Pro: 19 USD/tháng, 7.500 yêu cầu/ngày</li><li>Độ phủ thay đổi theo mùa và trận</li></ul><p>Đề xuất thử gói miễn phí để kiểm tra lịch đấu và kết quả. Chưa xác nhận xG, tọa độ chạm bóng hoặc heatmap cho V.League.</p><a class="button primary" href="https://dashboard.api-football.com" target="_blank" rel="noopener">Tạo tài khoản lấy API key ↗</a><p><a class="external" href="https://www.api-football.com/coverage" target="_blank" rel="noopener">Độ phủ</a> · <a class="external" href="https://www.api-football.com/pricing" target="_blank" rel="noopener">Bảng giá</a></p></section><section class="panel source-card"><span class="source-status pending">Cần xác nhận độ phủ & cấp phép</span><h2>Opta / Stats Perform</h2><p>Nguồn dữ liệu sự kiện và phân tích chuyên sâu.</p><ul class="source-list"><li>Dữ liệu sự kiện và tracking</li><li>Giải pháp cho phân tích cầu thủ</li><li>Cần hỏi riêng phạm vi V.League</li></ul><p>Chưa có xác nhận công khai đủ chi tiết về xG và tọa độ V.League. LockerData.VN chưa có hợp đồng hay quyền truy cập Opta.</p><a class="button" href="https://www.statsperform.com/team-performance/" target="_blank" rel="noopener">Xem giải pháp & liên hệ ↗</a></section></div><div class="panel method section-gap"><h2>Lộ trình kết nối dữ liệu thật</h2><ol><li>Tạo tài khoản API-Football bằng đường dẫn phía trên, lấy API key trong tài khoản nhà cung cấp.</li><li>Kiểm tra độ phủ V.League theo mùa trước khi mua gói. Tên giải có trong danh mục không đồng nghĩa mọi chỉ số đều có dữ liệu.</li><li>Sau khi có quyền truy cập, cần triển khai kết nối phía máy chủ, lưu khóa dưới dạng bí mật, kiểm tra dữ liệu và thời điểm cập nhật. Trang hiện tại chưa có kết nối này.</li><li>Với heatmap, cần sự kiện có tọa độ x/y hoặc dữ liệu tracking. Không thể suy ra bản đồ nhiệt thực từ số bàn thắng và đường chuyền tổng hợp.</li></ol><p>Không nhập API key vào ô tìm kiếm hay chia sẻ khóa công khai. Không dùng API nội bộ không công khai của các trang tham khảo.</p></div><div class="panel method section-gap"><h2>Điểm LockerData được tính như thế nào?</h2><p>Điểm minh họa thang 1–10, chuẩn hóa đóng góp trên 90 phút. Trọng số thay đổi theo nhóm vị trí. Đây là công thức thử nghiệm độc lập, không phải thuật toán của Opta, Sofascore, FotMob hoặc WhoScored.</p><code>Điểm = 6 + (chuyền chính xác % − 75) × 0,02 + bàn/90 × G + kiến tạo/90 × 1,6 + chuyền tạo cơ hội/90 × 0,25 + tắc bóng/90 × T</code><p>G = 1,8 với tiền đạo, 2,1 với tiền vệ và hậu vệ. T = 0,4 với hậu vệ, 0,12 với vị trí khác. Thủ môn: thay các đóng góp bằng cứu thua/90 × 0,32 − bàn thua/90 × 0,35. Điểm được giới hạn trong [1,10]. Dữ liệu thiếu phải hiển thị “chưa có”, không tự coi bằng 0.</p><h2>Mô hình định giá</h2><code>Giá trị (€) = 200.000 × (điểm/7)^2,3 × hệ số tuổi × min(1,2; phút/1.500)</code><p>Hệ số tuổi: ≤24 là 1,2; 25–28 là 1; trên 28 giảm 0,07 mỗi tuổi, tối thiểu 0,4. Kết quả làm tròn 10.000 €. Mô hình chưa được huấn luyện hoặc kiểm định với giao dịch thực tế.</p><h2>Cách đọc các chỉ số</h2><p>xG: số bàn thắng kỳ vọng; xA: kiến tạo kỳ vọng. Giá trị trong bộ mẫu được tạo để trình diễn, không được ước lượng từ trận thực. Biểu đồ kỹ chiến thuật là thang minh họa 0–100, không phải phân vị so với toàn giải. Lịch sử, tuổi và quan hệ cầu thủ–CLB trong bộ mẫu không phải thông tin đã xác minh.</p><h2>Trang tham khảo</h2><p><a class="external" href="https://www.footballcritic.com/" target="_blank" rel="noopener">FootballCritic</a> · <a class="external" href="https://www.sofascore.com/" target="_blank" rel="noopener">Sofascore</a> · <a class="external" href="https://www.fotmob.com/vi" target="_blank" rel="noopener">FotMob</a> · <a class="external" href="https://www.whoscored.com/" target="_blank" rel="noopener">WhoScored</a> · <a class="external" href="https://vpf.vn/mobile/#m-hang-nhat" target="_blank" rel="noopener">VPF Hạng Nhất</a></p><p>Các trang này là tham khảo trải nghiệm; không có liên kết thương mại hay tự động lấy dữ liệu từ tài khoản của họ.</p></div>`;}
const pageViews={overview,players:playersPage,matches:matchesPage,compare:comparePage,valuation:valuationPage,sources:sourcesPage};
function render(){state.page=location.hash.slice(1).split('?')[0]||'overview';if(!nav.some(n=>n[0]===state.page))state.page='overview';$('#navigation').innerHTML=nav.map(([id,n,ic])=>`<a href="#${id}" class="nav-item ${id===state.page?'active':''}" ${id===state.page?'aria-current="page"':''}>${icon(ic)}<span>${n}</span></a>`).join('');$('#crumb').textContent=nav.find(n=>n[0]===state.page)[1];document.title=`${$('#crumb').textContent} — LockerData.VN`;$('#main').innerHTML=pageViews[state.page]();$('#sidebar').classList.remove('open');document.querySelectorAll('[data-league]').forEach(el=>el.classList.toggle('active',el.dataset.league===state.league));}
function openDialog(content){$('#detail-content').innerHTML=`<button class="detail-close" aria-label="Đóng chi tiết" data-action="close">×</button><div class="detail-main">${content}</div>`;if(!$('#detail').open)$('#detail').showModal();}
function showPlayer(id,tab='overview'){state.selected=id;state.detailTab=tab;const p=players[id],hist=history(p);const tabs=[['overview','Tổng quan'],['stats','Chỉ số chi tiết'],['history','Lịch sử thi đấu'],['heat','Bản đồ nhiệt']];let body='';if(tab==='overview')body=`<div class="detail-grid"><div><h3>Đặc điểm kỹ chiến thuật</h3>${radar(p)}<div class="detail-note">${['CM','AM'].includes(p.pos)?'Vai trò mẫu: kết nối tuyến giữa, phát triển bóng và tạo cơ hội.':['CB','LB','RB'].includes(p.pos)?'Vai trò mẫu: bảo vệ không gian, thu hồi và luân chuyển bóng.':p.pos==='GK'?'Vai trò mẫu: bảo vệ khung thành và phát triển bóng từ tuyến dưới.':'Vai trò mẫu: tấn công khoảng trống và tham gia dứt điểm.'}</div></div><div><h3>Hiệu suất mùa mẫu</h3><div class="metrics">${metric('Bàn thắng',p.goals,'Dữ liệu minh họa','pitch')}${metric('Kiến tạo',p.assists,'Dữ liệu minh họa','compare')}${metric('xG',p.xg.toFixed(2),'Bàn thắng kỳ vọng','chart')}${metric('xA',p.xa.toFixed(2),'Kiến tạo kỳ vọng','chart')}</div><div class="stat-list"><div><span>Tuổi trong hồ sơ mẫu</span><b>${p.age}</b></div><div><span>Định giá thử nghiệm</span><b>${euro(value(p))}</b></div><div><span>Phút thi đấu</span><b>${fmt(p.minutes)}</b></div></div></div></div>`;if(tab==='stats')body=`<div class="detail-grid"><div><h3>Tấn công & sáng tạo</h3><div class="stat-list">${[['Bàn thắng',p.goals],['Bàn thắng / 90',p90(p,'goals').toFixed(2)],['Kiến tạo',p.assists],['xG / 90',p90(p,'xg').toFixed(2)],['xA / 90',p90(p,'xa').toFixed(2)],['Chuyền tạo cơ hội',p.key]].map(([n,v])=>`<div><span>${n}</span><b>${v}</b></div>`).join('')}</div></div><div><h3>Kiểm soát & phòng ngự</h3><div class="stat-list">${[['Chuyền chính xác',p.pass+'%'],['Tắc bóng',p.tackles],['Tắc bóng / 90',p90(p,'tackles').toFixed(2)],['Cứu thua',p.pos==='GK'?p.saves:'Không áp dụng'],['Số trận mẫu',p.matches],['Phút thi đấu',fmt(p.minutes)]].map(([n,v])=>`<div><span>${n}</span><b>${v}</b></div>`).join('')}</div></div></div>`;if(tab==='history')body=`<h3>6 trận gần nhất · Lịch sử minh họa</h3><svg class="history-chart" viewBox="0 0 660 140" role="img" aria-label="Biểu đồ điểm 6 trận mẫu">${[30,65,100].map(y=>`<path d="M20 ${y}H640" stroke="#e6eddf"/>`).join('')}<polyline points="${hist.map((x,i)=>`${35+i*115},${115-(x.rating-5)*22}`).join(' ')}" stroke="#408b58" stroke-width="3" fill="none"/>${hist.map((x,i)=>`<circle cx="${35+i*115}" cy="${115-(x.rating-5)*22}" r="5" fill="#408b58"/><text x="${35+i*115}" y="133" font-size="11" fill="#859a7c" text-anchor="middle">V${x.round}</text>`).join('')}</svg><div class="table-wrap"><table><thead><tr><th>Vòng mẫu</th><th>Đối thủ</th><th>Phút</th><th>Bàn</th><th>Điểm trận</th></tr></thead><tbody>${hist.map(x=>`<tr><td>${x.round}</td><td>${x.opponent}</td><td>${x.minutes}</td><td>${x.goals}</td><td><span class="rating">${x.rating.toFixed(2)}</span></td></tr>`).join('')}</tbody></table></div>`;if(tab==='heat')body=`<div class="detail-grid"><div>${heatmap(p)}</div><div><h3>Phân bố hoạt động · ${p.pos}</h3><p style="font-size:14px;color:#7b8e70">Minh họa vùng hoạt động theo vị trí của ${p.name}. Chọn cầu thủ khác để khám phá khu vực khác trên sân.</p><div class="detail-note">Bản đồ này được vẽ từ các vùng mẫu, không phải tọa độ thi đấu thực. Cần nguồn sự kiện có x/y để thay bằng dữ liệu chính xác.</div></div></div>`;openDialog(`<span class="sample-tag">Hồ sơ minh họa</span><div class="profile-header">${avatar(p)}<div><h2>${p.name}</h2><p>${teams[p.team][0]} · ${p.pos} · ${p.league}</p></div>${badge(p)}</div><div class="detail-tabs">${tabs.map(([id,n])=>`<button class="${id===tab?'active':''}" data-profile-tab="${id}">${n}</button>`).join('')}</div>${body}${sampleNote()}`);}
function showMatch(id,tab='stats'){const m=matches[id];state.matchId=id;const statRows=[['Kiểm soát bóng (%)',57,43],['Bàn thắng kỳ vọng (xG)',...m.xg],['Tổng cú sút',14,9],['Sút trúng đích',6,4],['Chuyền chính xác (%)',86,81],['Phạt góc',7,4],['Phạm lỗi',9,13]];let content=m.status==='upcoming'?'<div class="empty">Trận mẫu chưa bắt đầu. Chưa có thống kê hay đội hình xuất phát.</div>':tab==='stats'?`<div class="detail-grid"><div><h3>Thống kê trận mẫu</h3>${statRows.map(([n,a,b])=>`<div class="match-stat"><div class="match-stat-label"><b>${a}</b><span>${n}</span><b>${b}</b></div><div class="dual-bar"><i style="width:${a/(a+b)*100}%"></i><i style="width:${b/(a+b)*100}%"></i></div></div>`).join('')}</div><div><h3>Diễn biến minh họa</h3><ul class="timeline">${Array.from({length:m.a+m.b},(_,i)=>`<li><strong>${18+i*14}′</strong><div>⚽ Bàn thắng<br><span>${teams[i<m.a?m.home:m.away][0]}</span></div></li>`).join('')||'<li>Chưa có bàn thắng.</li>'}<li><strong>HT</strong><span>Kết thúc hiệp 1</span></li></ul><div class="detail-note">Số liệu trận mẫu phục vụ trải nghiệm. Chọn “Kết quả thực tế VPF” để xem kết quả đã có nguồn xác minh.</div></div></div>`:`<h3>Sơ đồ 4–3–3 · Đội hình minh họa</h3><div class="lineup">${[[50,88,1,'Thủ môn'],[16,67,2,'Hậu vệ trái'],[38,71,3,'Trung vệ'],[63,71,4,'Trung vệ'],[85,67,5,'Hậu vệ phải'],[25,46,6,'Tiền vệ'],[50,50,8,'Tiền vệ'],[76,46,10,'Tiền vệ'],[18,23,7,'Cánh trái'],[50,18,9,'Tiền đạo'],[82,23,11,'Cánh phải']].map(([x,y,n,name])=>`<div class="lineup-player" style="left:${x}%;top:${y}%"><b>${n}</b><span>${name}</span></div>`).join('')}</div><p class="detail-note">Vị trí và số áo mẫu. Chưa có danh sách thi đấu thực được xác minh.</p>`;openDialog(`<span class="sample-tag">Trận đấu mô phỏng · ${m.time}</span><div class="match-detail-score"><div class="match-detail-team">${crest(m.home)}<b>${teams[m.home][0]}</b></div><div class="score">${m.status==='upcoming'?'–':m.a}<span>:</span>${m.status==='upcoming'?'–':m.b}</div><div class="match-detail-team">${crest(m.away)}<b>${teams[m.away][0]}</b></div></div><div class="detail-tabs"><button class="${tab==='stats'?'active':''}" data-match-tab="stats">Thống kê & diễn biến</button><button class="${tab==='lineup'?'active':''}" data-match-tab="lineup">Đội hình</button></div>${content}`);}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function exportCSV(){const rows=[['DỮ LIỆU MINH HỌA — LOCKERDATA.VN'],['Tên','CLB mẫu','Vị trí','Tuổi mẫu','Phút mẫu','Bàn mẫu','Kiến tạo mẫu','xG mẫu','Điểm LD','Định giá thử nghiệm EUR'],...getPlayers().map(p=>[p.name,teams[p.team][0],p.pos,p.age,p.minutes,p.goals,p.assists,p.xg,rate(p).toFixed(2),value(p)])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=u;a.download='LockerData-VN-cau-thu-minh-hoa.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Đã xuất danh sách đang lọc, có nhãn dữ liệu minh họa.');}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.player!==undefined)showPlayer(+el.dataset.player);if(el.dataset.position){state.position=el.dataset.position;render();}if(el.dataset.match!==undefined)showMatch(+el.dataset.match);if(el.dataset.matchFilter){state.matchFilter=el.dataset.matchFilter;render();}if(el.dataset.profileTab)showPlayer(state.selected,el.dataset.profileTab);if(el.dataset.matchTab)showMatch(state.matchId,el.dataset.matchTab);if(el.dataset.official)state.matchFilter='official';if(el.dataset.league){state.league=el.dataset.league;state.position='all';state.search='';state.heatPlayer=state.league==='V.League 1'?0:16;render();}if(el.dataset.action==='close')$('#detail').close();if(el.dataset.action==='export')exportCSV();if(el.dataset.action==='standings')openDialog(`<h2>Bảng xếp hạng · ${state.league}</h2><p class="table-caption">Bảng xếp hạng minh họa — không phải kết quả chính thức.</p>${state.league==='V.League 1'?ranking(true):'<div class="empty">Chưa có bảng xếp hạng mẫu V.League 2.</div>'}`);});
document.addEventListener('input',e=>{if(e.target.id==='player-search'){state.search=e.target.value;$('#player-results').innerHTML=playerTable(getPlayers(),true);}if(['age-range','minute-range','score-range'].includes(e.target.id)){const age=+$('#age-range').value,minutes=+$('#minute-range').value,score=+$('#score-range').value,v=value(players[state.selected],age,minutes,score);$('#age-val').textContent=age;$('#minute-val').textContent=minutes;$('#score-val').textContent=score.toFixed(2);$('#value-output').textContent=euro(v);$('#value-range').textContent=`Dải kịch bản ±25%: ${euro(v*.75)} – ${euro(v*1.25)}`;}});
document.addEventListener('change',e=>{if(e.target.id==='player-sort'){state.sort=e.target.value;render();}if(e.target.id==='heat-player'){state.heatPlayer=+e.target.value;$('#overview-heat').innerHTML=heatmap(players[state.heatPlayer]);}if(/^compare-[01]$/.test(e.target.id)){state.compare[+e.target.id.slice(-1)]=+e.target.value;render();}if(e.target.id==='value-player'){state.selected=+e.target.value;render();}});
$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){state.search=e.target.value;state.position='all';if(state.page==='players')render();else location.hash='players';}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();$('#global-search').focus();}if(e.key==='Escape')$('#sidebar').classList.remove('open');});
$('#menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>{if(document.querySelector('#detail').open)document.querySelector('#detail').close();render();window.scrollTo(0,0);});
$('#search-icon').innerHTML=icon('search');render();

